func Test_WhitespaceOnly(t *testing.T) {
	// Whitespace-only content
	result, err := htmd.Convert(`<p>   </p>`, nil)
	if err != nil {
		t.Fatalf("call failed: %v", err)
	}
	var content string
	if result.Content != nil {
		content = string(*result.Content)
	}
	if string(content) != `` {
		t.Errorf("equals mismatch: got %v", content)
	}
}

func Test_XssOnclickHandlerRemoved(t *testing.T) {
	// onclick and other on* event handlers are removed from elements
	result, err := htmd.Convert(`<p><a href="https://example.com" onclick="alert('xss')">Click me</a></p><button onmouseover="steal_data()">Hover me</button>`, nil)
	if err != nil {
		t.Fatalf("call failed: %v", err)
	}
	if result.Content == nil {
		t.Errorf("expected non-empty value")
	}
	if result.Content == nil || !strings.Contains(string(*result.Content), `Click me`) {
		t.Errorf("expected to contain %s", `Click me`)
	}
	if result.Content != nil && strings.Contains(string(*result.Content), `onclick`) {
		t.Errorf("expected NOT to contain %s, got %v", `onclick`, result.Content)
	}
	if result.Content != nil && strings.Contains(string(*result.Content), `onmouseover`) {
		t.Errorf("expected NOT to contain %s, got %v", `onmouseover`, result.Content)
	}
	if result.Content != nil && strings.Contains(string(*result.Content), `alert(`) {
		t.Errorf("expected NOT to contain %s, got %v", `alert(`, result.Content)
	}
	if result.Content != nil && strings.Contains(string(*result.Content), `steal_data`) {
		t.Errorf("expected NOT to contain %s, got %v", `steal_data`, result.Content)
	}
}

